    54  zip_source_t *
    55  zip_source_crc_create(zip_source_t *src, int validate, zip_error_t *error) {
    56      struct crc_context *ctx;
    57
    58      if (src == NULL) {
    59          zip_error_set(error, ZIP_ER_INVAL, 0);
    60          return NULL;
    61      }
    62
    63      if ((ctx = (struct crc_context *)malloc(sizeof(*ctx))) == NULL) {
    64          zip_error_set(error, ZIP_ER_MEMORY, 0);
    65          return NULL;
    66      }
    67
    68      zip_error_init(&ctx->error);
    69      ctx->validate = validate;
    70      ctx->crc_complete = 0;
    71      ctx->crc_position = 0;
    72      ctx->crc = (zip_uint32_t)crc32(0, NULL, 0);
    73      ctx->size = 0;
    74
    75      return zip_source_layered_create(src, crc_read, ctx, error);
    76  }
